// Wavetables (SPEC §9.15): band-limited int16 single cycles generated by tools/gen_wavetables.py (additive,
// peak 29000) and stored as const data, so they live in flash. Four sets with harmonic caps 40 / 16 / 6 / 3 and
// lengths 2048 / 512 / 256 / 128 serve MIDI <= 60 / 61..76 / 77..93 / >= 94, so no partial folds over Nyquist in
// the range a set is used for. 20 tables (+ one guard sample each) = 29 480 B of flash, resident in the 32 KB
// data cache.
#include "wavetables.h"
#include <math.h>
#include "../core/config.h"

namespace lp {
namespace {

#include "wavetables_data.hpp"

static_assert(sizeof(kWaveSine0) / sizeof(kWaveSine0[0]) == (size_t)kWaveLen + 1, "set 0 length (+ guard)");
static_assert(sizeof(kWaveSaw1) / sizeof(kWaveSaw1[0]) == (size_t)(1 << kWaveSetShift[1]) + 1, "set 1 length (+ guard)");
static_assert(sizeof(kWaveSaw2) / sizeof(kWaveSaw2[0]) == (size_t)(1 << kWaveSetShift[2]) + 1, "set 2 length (+ guard)");
static_assert(sizeof(kWaveSaw3) / sizeof(kWaveSaw3[0]) == (size_t)(1 << kWaveSetShift[3]) + 1, "set 3 length (+ guard)");
static_assert((1 << kWaveShift) == kWaveLen && kWaveSetShift[0] == kWaveShift, "kWaveShift must be log2(kWaveLen)");
static_assert(sizeof(kWaveSetTables) / sizeof(kWaveSetTables[0]) == (size_t)kWaveSetCount, "wavetable set count");
static_assert(sizeof(kWaveSetTables[0]) / sizeof(kWaveSetTables[0][0]) == (size_t)WaveCount, "waves per set");
static_assert(sizeof(kWaveSetHarmonicsData) / sizeof(kWaveSetHarmonicsData[0]) == (size_t)kWaveSetCount, "set count");
// The generator (tools/gen_wavetables.py SETS) and the header's constants must describe the same tables.
static_assert(kWaveSetHarmonicsData[0] == kWaveSetHarmonics[0] && kWaveSetHarmonicsData[1] == kWaveSetHarmonics[1] &&
              kWaveSetHarmonicsData[2] == kWaveSetHarmonics[2] && kWaveSetHarmonicsData[3] == kWaveSetHarmonics[3],
              "wavetables.h kWaveSetHarmonics out of date");
static_assert(kWaveSetShiftData[0] == kWaveSetShift[0] && kWaveSetShiftData[1] == kWaveSetShift[1] &&
              kWaveSetShiftData[2] == kWaveSetShift[2] && kWaveSetShiftData[3] == kWaveSetShift[3],
              "wavetables.h kWaveSetShift out of date");
static_assert(kWaveSetMinPitchData[0] == kWaveSetMinPitch[0] && kWaveSetMinPitchData[1] == kWaveSetMinPitch[1] &&
              kWaveSetMinPitchData[2] == kWaveSetMinPitch[2] && kWaveSetMinPitchData[3] == kWaveSetMinPitch[3],
              "wavetables.h kWaveSetMinPitch out of date");

inline int waveIndex(Wave w) { return w < WaveCount ? (int)w : (int)WSine; }   // out of range falls back to sine
inline int setIndex(int set) { return set < 0 ? 0 : set >= kWaveSetCount ? kWaveSetCount - 1 : set; }

} // namespace

const int16_t* waveTable(Wave w) { return kWaveSetTables[0][waveIndex(w)]; }

const int16_t* waveTable(Wave w, int midiPitch) { return kWaveSetTables[waveSetForPitch(midiPitch)][waveIndex(w)]; }

const int16_t* waveTableSet(Wave w, int set) { return kWaveSetTables[setIndex(set)][waveIndex(w)]; }

// (hz / kSampleRate) * 2^32, clamped to Nyquist so the result always fits (2^31 at fs/2).
uint32_t phaseIncForHz(float hz) {
  if (!(hz > 0.0f)) return 0;                     // negative, zero or NaN
  const float nyquist = 0.5f * (float)kSampleRate;
  if (hz > nyquist) hz = nyquist;
  return (uint32_t)(hz * (4294967296.0f / (float)kSampleRate));
}

// 440 * 2^((midi - 69) / 12), A4 = 440 (SPEC §5); ln(2)/12 = 0.0577622650.
float midiToHz(float midi) { return 440.0f * expf(0.057762265f * (midi - 69.0f)); }

} // namespace lp
